(()=>{'use strict';const key='study-site-theme',root=document.documentElement,system=matchMedia('(prefers-color-scheme: dark)');let choice;try{choice=localStorage.getItem(key);}catch{}let dark=choice==='dark'||(choice!=='light'&&system.matches);
function apply(){root.dataset.theme=dark?'dark':'light';root.style.colorScheme=dark?'dark':'light';document.querySelectorAll('.night-toggle').forEach(b=>{b.setAttribute('aria-pressed',String(dark));b.setAttribute('aria-label',dark?'Switch to light mode':'Switch to dark mode');b.title=dark?'Switch to light mode':'Switch to dark mode';b.innerHTML=`<span class="night-icon" aria-hidden="true">${dark?'☀':'☾'}</span><span class="night-label">${dark?'Light mode':'Dark mode'}</span>`;});const meta=document.querySelector('meta[name="theme-color"]');if(meta)meta.content=dark?'#10121f':'#f5f3eb';}
function mount(){if(document.querySelector('.night-toggle'))return;const target=document.querySelector('header .top-right')||document.querySelector('body > header');if(!target)return;const b=document.createElement('button');b.type='button';b.className='night-toggle';b.onclick=()=>{dark=!dark;choice=dark?'dark':'light';try{localStorage.setItem(key,choice);}catch{}apply();};if(target.matches('header'))target.insertBefore(b,target.querySelector('nav'));else target.append(b);apply();}
apply();function start(){mount();new MutationObserver(mount).observe(document.body,{childList:true,subtree:true});}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',start,{once:true});else start();system.addEventListener('change',e=>{if(choice!=='light'&&choice!=='dark'){dark=e.matches;apply();}});addEventListener('storage',e=>{if(e.key===key){choice=e.newValue;dark=choice==='dark'||(choice!=='light'&&system.matches);apply();}});})();
